const rejectingProvider = (reason: unknown): AIProvider => ({
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw reason;
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

describe('ChatOrchestrator non-Error coercion', () => {
  it('coerces a thrown string to an Error for onError', async () => {
    let seenError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        seenError = error;
      },
    };

    const orchestrator = createChatOrchestrator(rejectingProvider('boom'), promptBuilder, undefined, {hooks});

    // We expect it to still reject to the caller with the original string
    const result = await orchestrator.processMessage(createSession('hi')).catch(e => e);

    expect(result).toBe('boom');
    expect(seenError).toBeInstanceOf(Error);
    expect(seenError?.message).toBe('boom');
    // Using any because 'cause' is standard in Node 16.9.0+ but TS might need target/lib update
    expect((seenError as any).cause).toBe('boom');
  });

  it('coerces a thrown object to an Error for onError', async () => {
    let seenError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        seenError = error;
      },
    };

    const reason = {code: 503, detail: 'upstream down'};
    const orchestrator = createChatOrchestrator(rejectingProvider(reason), promptBuilder, undefined, {hooks});

    const result = await orchestrator.processMessage(createSession('hi')).catch(e => e);

    expect(result).toBe(reason);
    expect(seenError).toBeInstanceOf(Error);
    expect(seenError?.message).toBe('upstream down');
    expect((seenError as any).cause).toBe(reason);
  });

  it('coerces undefined to an Error for onError', async () => {
    let seenError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        seenError = error;
      },
    };

    const orchestrator = createChatOrchestrator(rejectingProvider(undefined), promptBuilder, undefined, {hooks});

    const result = await orchestrator.processMessage(createSession('hi')).catch(e => e);

    expect(result).toBeUndefined();
    expect(seenError).toBeInstanceOf(Error);
    expect(seenError?.message).toBe('undefined');
    expect((seenError as any).cause).toBeUndefined();
  });
});

